    preparation: ["Create an inventory that includes patio and closet items.", "Measure large furniture and key doorways in your new home.", "Arrange safe space for children and pets during loading.", "Set aside bedding, medication, chargers, and first-night essentials."],
    areas: { text: "We move households locally across Miami-Dade, Broward, and Palm Beach counties, from city apartments to single-family neighborhoods. These area pages offer useful details for planning around your home.", cities: [{ href: "/miami-movers", label: "Miami" }, { href: "/hollywood-fl-movers", label: "Hollywood" }, { href: "/boca-raton-movers", label: "Boca Raton" }] },
